const fs = require('fs');
const path = require('path');
const { isAllowedRegion } = require('../validation/RegionValidator');

const CONFIG_DIR = path.join(__dirname, '../../config/regions');
const configCache = new Map();

function handleRegionConfig(req, res) {
  const region = req.query.region;
  if (!isAllowedRegion(region)) {
    res.status(400).send('invalid region');
    return;
  }
  const config = loadRegionConfig(region);
  res.json(config);
}

function loadRegionConfig(region) {
  if (configCache.has(region)) {
    return configCache.get(region);
  }
  const raw = fs.readFileSync(path.join(CONFIG_DIR, region + '.json'), 'utf8');
  const parsed = JSON.parse(raw);
  configCache.set(region, parsed);
  return parsed;
}

module.exports = { handleRegionConfig };
